import json, csv, math

with open('/root/campaign_manifest.json') as f:
    manifest = json.load(f)

def read_csv(path):
    with open(path, newline='') as f:
        return list(csv.DictReader(f))

crate_cost_rows = read_csv('/root/crate_cost.csv')
billing_rows = read_csv('/root/billing.csv')
override_rows = read_csv('/root/location_overrides.csv')
suspension_rows = read_csv('/root/suspensions.csv')


def r2(x):
    # Avoid float representation noise (e.g. 12.799999999) before rounding.
    return round(float(x) + 1e-12, 2)


def is_blank(v):
    return v is None or str(v).strip() == ''


def flatten_manifest(m):
    out = []
    for region in m.get('regions', []):
        for c in region.get('campaigns', []):
            out.append(c)
    return out


# 2b — Filter campaigns
all_campaigns = flatten_manifest(manifest)
retained = [c for c in all_campaigns if c.get('analysis_flag') == 'review']

suspended_ids = {
    r.get('campaign_id')
    for r in suspension_rows
    if (r.get('suspension_status') == 'hold')
}

retained = [c for c in retained if c.get('campaign_id') not in suspended_ids]


# Helpers for resolution steps
crate_cost_by_tier = {}
for r in crate_cost_rows:
    tier = r.get('crate_tier')
    if tier is None:
        continue
    crate_cost_by_tier[tier] = float(r['crate_cost_usd'])


def resolve_billing_payment_usd(campaign):
    name = campaign.get('campaign_name')
    aliases = set(campaign.get('alias_labels') or [])

    matches = []
    for r in billing_rows:
        label = r.get('campaign_label')
        if label == name or label in aliases:
            if r.get('status') == 'active':
                matches.append(r)

    if not matches:
        raise ValueError(f"No active billing rows matched campaign_id={campaign.get('campaign_id')}")

    # Lexicographically largest cycle_tag
    best = max(matches, key=lambda r: r.get('cycle_tag') or '')
    return float(best['payment_per_dispatch_per_clinic_usd'])


def resolve_active_clinics(campaign):
    cid = campaign.get('campaign_id')

    qualifying = []
    for r in override_rows:
        if r.get('campaign_id') != cid:
            continue
        if r.get('state') != 'approved':
            continue
        if is_blank(r.get('revision')):
            continue
        if is_blank(r.get('active_clinics')):
            continue

        try:
            rev_num = int(str(r.get('revision')).strip())
        except Exception:
            continue

        qualifying.append((rev_num, r))

    if qualifying:
        rev_num, row = max(qualifying, key=lambda t: t[0])
        return int(str(row['active_clinics']).strip())

    return int(campaign['default_active_clinics'])


def compute_figures(drug_cost_per_1000_doses_usd, doses_per_day, active_clinics, crate_cost_usd, payment_per_dispatch_per_clinic_usd, days_per_dispatch, dispatches_per_year):
    annual_revenue = payment_per_dispatch_per_clinic_usd * active_clinics * dispatches_per_year
    annual_drug_cost = (
        drug_cost_per_1000_doses_usd
        * active_clinics
        * doses_per_day
        * days_per_dispatch
        * dispatches_per_year
        / 1000.0
    )

    # crate_cost_usd is interpreted as per-dispatch cost based on the CSV header/value.
    annual_crate_cost = crate_cost_usd * dispatches_per_year

    annual_margin = annual_revenue - annual_drug_cost - annual_crate_cost

    return {
        'annual_revenue_usd': r2(annual_revenue),
        'annual_drug_cost_usd': r2(annual_drug_cost),
        'annual_crate_cost_usd': r2(annual_crate_cost),
        'annual_margin_usd': r2(annual_margin),
    }


campaign_outputs = []

for c in retained:
    crate_tier = c['crate_tier']
    if crate_tier not in crate_cost_by_tier:
        raise ValueError(f"Unknown crate_tier={crate_tier} for campaign_id={c.get('campaign_id')}")

    crate_cost_usd = float(crate_cost_by_tier[crate_tier])
    payment = resolve_billing_payment_usd(c)
    active_clinics = resolve_active_clinics(c)

    base = {
        'campaign_id': c['campaign_id'],
        'campaign_name': c['campaign_name'],
        'crate_tier': crate_tier,
        'active_clinics': active_clinics,
        'payment_per_dispatch_per_clinic_usd': r2(payment),
        'drug_cost_per_1000_doses_usd': r2(c['drug_cost_per_1000_doses_usd']),
        'doses_per_day': int(c['doses_per_day']),
        'crate_cost_usd': r2(crate_cost_usd),
    }

    model_6 = compute_figures(
        drug_cost_per_1000_doses_usd=float(c['drug_cost_per_1000_doses_usd']),
        doses_per_day=float(c['doses_per_day']),
        active_clinics=active_clinics,
        crate_cost_usd=crate_cost_usd,
        payment_per_dispatch_per_clinic_usd=payment,
        days_per_dispatch=6,
        dispatches_per_year=60,
    )

    model_12 = compute_figures(
        drug_cost_per_1000_doses_usd=float(c['drug_cost_per_1000_doses_usd']),
        doses_per_day=float(c['doses_per_day']),
        active_clinics=active_clinics,
        crate_cost_usd=crate_cost_usd,
        payment_per_dispatch_per_clinic_usd=payment,
        days_per_dispatch=12,
        dispatches_per_year=30,
    )

    diff = r2(model_12['annual_margin_usd'] - model_6['annual_margin_usd'])

    campaign_outputs.append({
        **base,
        'model_6_day': model_6,
        'model_12_day': model_12,
        'difference_usd': diff,
    })


campaign_outputs.sort(key=lambda x: x['campaign_id'])


total_margin_6 = r2(sum(c['model_6_day']['annual_margin_usd'] for c in campaign_outputs))
total_margin_12 = r2(sum(c['model_12_day']['annual_margin_usd'] for c in campaign_outputs))
total_diff = r2(total_margin_12 - total_margin_6)
abs_diff = r2(abs(total_diff))

threshold = 11000.0
if abs_diff < threshold:
    decision = 'move_to_12_day'
else:
    decision = 'keep_6_day'

analysis = {
    'assumptions': {
        'models': {
            '6_day': {'days_per_dispatch': 6, 'dispatches_per_year': 60},
            '12_day': {'days_per_dispatch': 12, 'dispatches_per_year': 30},
        },
        'crate_cost_interpretation': 'crate_cost_usd in crate_cost.csv is treated as a per-dispatch cost and multiplied by dispatches_per_year to produce annual_crate_cost',
        'override_rule': 'Filter location_overrides.csv to rows matching campaign_id, state == "approved", non-blank revision, and non-blank active_clinics; pick the row with the highest numeric revision; otherwise use default_active_clinics from the manifest',
        'suspension_rule': 'Exclude campaigns whose campaign_id appears in suspensions.csv with suspension_status == "hold"',
    },
    'campaigns': campaign_outputs,
    'totals': {
        'total_margin_6_day_usd': total_margin_6,
        'total_margin_12_day_usd': total_margin_12,
        'total_diff_usd': total_diff,
        'abs_diff_usd': abs_diff,
        'threshold_usd': r2(threshold),
    },
    'recommendation': {
        'decision': decision,
        'justification': f"Absolute difference is ${abs_diff:.2f}, which is {'below' if abs_diff < threshold else 'at or above'} the $11000 threshold.",
    },
}

with open('/root/vaxcrate_analysis.json', 'w') as f:
    json.dump(analysis, f, indent=2)

with open('/root/vaxcrate_summary.md', 'w') as f:
    f.write(f"Total 6-day margin (USD): {total_margin_6:.2f}\n")
    f.write(f"Total 12-day margin (USD): {total_margin_12:.2f}\n")
    f.write(f"Absolute difference (USD): {abs_diff:.2f}\n")
    f.write(f"Decision: {decision}\n")

